MATCH (ss:SUB_SPLITTER)
WHERE NOT exists{ (ss)-[:CONNECTS_TO*1..]->(:ONT) }
RETURN ss

MATCH (s:SUB_SPLITTER)
WHERE NOT exists {    
MATCH (s)-[:CONNECTS_TO]->(:ONT) }
RETURN s

MATCH (c:CARD)
WHERE NOT EXISTS {  
MATCH (c)-[:CONNECTS_TO]->(:PORT) }
RETURN c

MATCH (c:CABIN)
WHERE NOT EXISTS {  
MATCH (c)-[:BACKUP_FOR]->(:CABIN) }
RETURN c
